// TH18 v1.00a st06bs.ecl.txt BossCard4 (s:1085-1164) + BossCard4_at (s:1165-1222).
// Target card t0 = source BossCard4 entry; a 120-frame practice buffer precedes it.
// Control enemy at (0,0) owns the spell and has no body collision; the real boss
// at (0,128) keeps the source hurtbox/body box and runs the whole attack.
const TIME_LIMIT: int = 3120;   // 120 opening buffer + 3000 source spell timeout
const SOURCE_LIMIT: int = 3000;
const OPENING_BUFFER: int = 120;
const TH18_DROPLET: int = 896;  // s:1170 etSprite(A,34,B): type34 Droplet, radius 2.4

// s:1174-1186: ANIM(type2,a=1), OFFSCREEN(0x100,a=300), WAIT(-2^31,60),
// VELTIME(0x200000,a=240, keep current angle, target scalar speed 1.5/2/3).
// Birth slowdown/no-hit window omitted per policy; ANIM's position-=4*velocity
// retreat is kept on the spawn point at fire time. @N is post-delay, so the
// keep-alive runs at birth, accel starts at +60 and stops 240 frames later.
xformdef DROPLET_ACCEL(delta: fx) {
    @60 offscreen_keep(300);
    @240 set_accel(delta);
    set_accel(0fx);
}

// s:1165-1222 BossCard4_at. One stream per source et slot A=0..6.
// s:1171 etCount(A,1,1) + s:1172 etAim(A,3) + s:1173 etAngle(A,C,..):
// mode3 with N=1 is a single bullet at direction C (no player aim).
async sub stream(color: int, c: angle, start_e: int, end_e: int, ramp: int, delta: fx) {
    var d: angle = 0deg;
    var jb: int = 0;
    var base: angle = 0deg;
    var out: angle = 0deg;
    var sx: fx = 0fx;
    var sy: fx = 0fx;
    var age: int = 0;
    var f: int = 0;
    loop {
        if $frame >= self_int(1) { return; }
        // s:1205-1206 target center (0,224); s:1211 D = angle from FINAL to center.
        d = atan2(224fx - $self_y, 0fx - $self_x);
        // s:1210 one RANDF2 read per shot; 0.017453292 rad = 1 deg ~= 182 BAM.
        jb = rand(365) - 182;
        base = d + c + (jb as angle);      // s:1212 bullet direction
        out = d + c + 180deg;              // s:1214 offsetRad(direction+pi,320)
        // s:1213-1214 spawn point = center + 320 at `out`; ANIM a=1 retreat 4*1.2.
        sx = 320fx * cos(out) - 4.8fx * cos(base);
        sy = 224fx + 320fx * sin(out) - 4.8fx * sin(base);
        // s:1215 etOn(A) reads the FINAL position used above.
        _ = fire(TH18_DROPLET, color, sx, sy, 1.2fx, base, DROPLET_ACCEL(delta), none);
        // s:1197-1204,1216-1217: floatTime ramps the interval start->end over
        // `ramp` frames; the wait uses trunc(E). $self_age is 1 on the first run.
        age = $self_age - 1;
        if age >= ramp {
            f = end_e;
        } else {
            f = (start_e * (ramp - age) + end_e * age) / ramp;
        }
        wait(f);
    }
}

// s:1085-1164 BossCard4.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);                 // s:33 setHurtbox(40,40) / 2
    set_hitbox(24fx);                  // s:34 setHitbox(48,48) / 2
    wait(OPENING_BUFFER);              // shell buffer; source t0 begins after this
    set_self_int(1, $frame + SOURCE_LIMIT);
    // s:1196-1204 interval ramp and s:1177-1186 VELTIME target speed per rank.
    var rank: int = global(GVAR_RANK);
    var start_e: int = 30;
    var end_e: int = 10;
    var ramp: int = 1800;
    var delta: fx = 0.003333fx;        // (2.0-1.2)/240
    if rank == 0 { start_e = 40; end_e = 30; delta = 0.00125fx; }        // 1.5
    if rank == 2 { start_e = 15; end_e = 7; ramp = 2400; }               // 2.0
    if rank == 3 { start_e = 10; end_e = 5; ramp = 2400; delta = 0.0075fx; } // 3.0
    // s:1123 movePosTime(60,4, 0,-128)
    move_to(60, 0fx, -128fx, EASE_QUAD_OUT);
    wait(60);                          // s:1127 +60 label (ANM/playSound omitted)
    wait(60);                          // s:1131 +120 label
    // s:1135-1147 seven async streams, two frames apart.
    spawn stream(4, 120deg, start_e, end_e, ramp, delta);
    wait(2);
    spawn stream(6, 80deg, start_e, end_e, ramp, delta);
    wait(2);
    spawn stream(8, 40deg, start_e, end_e, ramp, delta);
    wait(2);
    spawn stream(10, 0deg, start_e, end_e, ramp, delta);
    wait(2);
    spawn stream(13, -40deg, start_e, end_e, ramp, delta);
    wait(2);
    spawn stream(14, -80deg, start_e, end_e, ramp, delta);
    wait(2);
    spawn stream(2, -120deg, start_e, end_e, ramp, delta);
    // s:1148 movePos(0,224) then s:1151 moveCircle(-pi/2, +0.008726646, 320,0):
    // center C=(0,224), phase -90deg, r=320 => immediate position (0,-96).
    move_to(0, 0fx, -96fx, EASE_LINEAR);
    var sgn: int = 1;
    var e: int = 0;
    loop {
        if $frame >= self_int(1) { return; }
        // s:1151/1153: 720 frames per half-turn, full 360deg, then reverse.
        if e == 720 {
            e = 0;
            sgn = 0 - sgn;
        }
        var a0: int = -16384 + sgn * (65536 * e) / 720;
        var a1: int = -16384 + sgn * (65536 * (e + 1)) / 720;
        var x0: fx = 320fx * cos(a0 as angle);
        var y0: fx = 224fx + 320fx * sin(a0 as angle);
        var x1: fx = 320fx * cos(a1 as angle);
        var y1: fx = 224fx + 320fx * sin(a1 as angle);
        // Target order is ECL->integration; pre-place this frame's circle step.
        move_vel_xy(0, x1 - x0, y1 - y0, EASE_LINEAR);
        e = e + 1;
        wait(1);
    }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // s:1113 setInterrupt(0,0,3000,"Boss5"); s:1115 spell(72,3000,0).
    spell_begin(0, 72, none, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    // Entry position: Boss() s:14 movePos(0,128) / Boss4 s:404 moveLimit center.
    _ = spawn_enemy(0fx, 128fx, 18700, 0, 0, 0, boss_main);
    loop { wait(600); }
}
